/**
 * ARTICLE ENGINE. One collection: the town articles, "<hub> in <Town>", one
 * per hub per town (plan: 9 hubs x 100 towns = 900, src/data/article-queue.json
 * lists them in publish order). Files live at src/content/articles/<hub>/<town-slug>.md
 * and render at /<hub>/<town-slug>/. Nothing is generated by the build: mass
 * generation runs after handoff (docs/ARTICLE-ENGINE.md has the writing rules).
 * A file with draft: true, or a publishDate in the future, is not published.
 */
import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';

const hubSlugs = [
  'wood-fired-hot-tubs', 'hot-tub-repair-and-servicing', 'electric-hot-tubs', 'hot-tub-installation',
  'swimming-pools-and-swim-spas', 'saunas', 'arctic-spas-dealer', 'commercial-and-mosaic-tiled-spas',
  'trade-and-holiday-park-hot-tubs',
] as const;

const articles = defineCollection({
  loader: glob({ pattern: '**/[^_]*.md', base: './src/content/articles' }),
  schema: z.object({
    title: z.string(),
    description: z.string().max(170),
    hub: z.enum(hubSlugs),
    town: z.string(),
    townSlug: z.string(),
    publishDate: z.coerce.date(),
    updatedDate: z.coerce.date().optional(),
    draft: z.boolean().default(false),
    takeaways: z.array(z.string()).min(3).max(6),
    faqs: z.array(z.object({ q: z.string(), a: z.string() })).default([]),
    /** Optional per-article picks from the R2 pool; otherwise the hub's picks fill the slots. */
    images: z.array(z.object({ src: z.string(), alt: z.string() })).default([]),
    /** YouTube video id, once the channel exists (operator supplies it). Click-to-load facade. */
    youtube: z.string().optional(),
  }),
});

export const collections = { articles };
